-- ══ Ellenőrzés ═══════════════════════════════════════════
-- A blokkban nem maradhat csonk: tizennégy kidolgozott kórkép várható
-- (kilenc elektrolit, négy sav-bázis, és az átsorolt hyperkalaemia).
select
  case when body ->> 'brief_what' is null then 'csonk' else 'kidolgozott' end as allapot,
  count(*) as darab,
  string_agg(name, ', ' order by name) as korkepek
from public.diseases
where specialty = 'Elektrolit- és sav-bázis' and status = 'published'
group by 1
order by 1;
